-- تسريبات القدرات – الأربعاء ١١ نوفمبر ٢٠٢٦
-- 24 سؤالاً: كمي 12 + لفظي 12 (منها 3 في 2 قطع استيعاب)
-- آمن لإعادة التشغيل: guard على وجود أسئلة المجموعة
-- ═══════════════════════════════════════════════════════════════
BEGIN;

INSERT INTO leak_groups (id, title, leak_date, section, question_count, description, is_active, accent_color)
VALUES ('ad111126-2026-4c00-9d00-111120260001', 'تسريبات القدرات – الأربعاء ١١ نوفمبر ٢٠٢٦', '2026-11-11', 'mixed', 24, 'أسئلة اختبار القدرات المحوسب ليوم الأربعاء ١١ نوفمبر ٢٠٢٦ — القسمان الكمي واللفظي مع الشروح.', true, '#6D28D9')
ON CONFLICT (id) DO NOTHING;

DO $mig$
BEGIN
IF EXISTS (SELECT 1 FROM questions WHERE leak_group_id = 'ad111126-2026-4c00-9d00-111120260001') THEN
  RAISE NOTICE 'أسئلة المجموعة موجودة مسبقاً — تخطي الإدراج';
ELSE
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'التحليل', 'اختيار من متعدد', 'أوجد الحد التالي في المتتابعة: ١١، ١٣، ١٢، ١٤، ١٣، ١٥، ...', '["١٤", "١٥", "١٦", "١٧"]'::jsonb, 0, 'نبحث عن طريقة الانتقال بين الحدود. نلاحظ أننا نضيف ٢ ثم نطرح ١ بالتناوب: ١١ + ٢ = ١٣، ثم ١٣ − ١ = ١٢. بعد الحد ١٥ نطرح ١، فيكون الحد التالي ١٤.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'حصل طلاب فصل على الدرجات من ١ إلى ٨، وكانت أعدادهم على الترتيب: ٢، ٥، ٤، ١٠، ١٢، ١٥، ١٣، ١٤ طالبًا. ما الدرجة التي حصل عليها أكبر عدد من الطلاب؟', '["٣", "٤", "٥", "٦"]'::jsonb, 3, 'نبحث عن أكبر عدد في قائمة أعداد الطلاب، وهو ١٥ طالبًا. هذا العدد هو السادس في الترتيب، أي يقابل الدرجة ٦. إذن الدرجة التي حصل عليها أكبر عدد من الطلاب هي ٦.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في الشكل مستقيمان متوازيان يصل بينهما خط منكسر. ما قياس الزاوية س؟', '["٣٠°", "٥٠°", "٨٠°", "٢٨٠°"]'::jsonb, 2, 'عند وجود مستقيمين متوازيين، يمكن رسم مستقيم موازٍ لهما يمر برأس الزاوية س. تتوزع الزاوية عند الرأس إلى زاويتين تساويان ٣٧° و٤٣° بالتبادل الداخلي. إذن س = ٣٧° + ٤٣° = ٨٠°.', 'https://czzcmbxejxbotjemyuqf.supabase.co/storage/v1/object/public/question-figures/qudurat_nov11_q011_zigzag.png', 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في الشكل مستقيمان يتقاطعان بين ضلعين رأسيين متوازيين. ما قياس الزاوية س؟', '["٤٠°", "٥٠°", "٦٠°", "٧٠°"]'::jsonb, 1, 'الزاويتان المتقابلتان بالرأس متساويتان، لذا الزاوية عند تقاطع المستقيمين داخل المثلث الأيمن تساوي ٧٠°. مجموع زوايا أي مثلث يساوي ١٨٠°. إذن س = ١٨٠° − ٧٠° − ٦٠° = ٥٠°.', 'https://czzcmbxejxbotjemyuqf.supabase.co/storage/v1/object/public/question-figures/qudurat_nov11_q014_cross.png', 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في الشكل مثلث قائم الزاوية، والقطعتان المعلَّمتان بالشرطة متساويتان في الطول. ما قياس الزاوية س؟', '["١٠°", "٢٠°", "٣٠°", "٤٠°"]'::jsonb, 1, 'نبدأ بالمثلث الصغير القائم: الزاوية عند القاعدة = ١٨٠° − ٩٠° − ٥٠° = ٤٠°. الزاوية المجاورة لها على الخط المستقيم = ١٨٠° − ٤٠° = ١٤٠°. ولأن المثلث الآخر متساوي الساقين، فإن زاويتي قاعدته متساويتان، فتكون س = (١٨٠° − ١٤٠°) ÷ ٢ = ٢٠°.', 'https://czzcmbxejxbotjemyuqf.supabase.co/storage/v1/object/public/question-figures/qudurat_nov11_q016_isos.png', 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'مثلث متساوي الساقين طول قاعدته ١٢ سم ومساحته ٤٨ سم². ما طول ساقه بالسنتيمتر؟', '["٦", "٨", "١٠", "١٢"]'::jsonb, 2, 'نستخدم قانون مساحة المثلث: المساحة = (القاعدة × الارتفاع) ÷ ٢. بالتعويض: ٤٨ = (١٢ × الارتفاع) ÷ ٢، فيكون الارتفاع = ٨ سم. وبما أن المثلث متساوي الساقين فإن الارتفاع ينصف القاعدة إلى جزأين طول كل منهما ٦ سم، ومن فيثاغورس نحصل على س = √(٦² + ٨²) = ١٠ سم.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في دائرة مركزها م، إذا كانت الزاوية المركزية ب م ج تساوي ٣٦°، فما قياس القوس الصغير ب ج؟', '["١٨°", "٣٦°", "٥٤°", "٧٢°"]'::jsonb, 1, 'قياس القوس الصغير في الدائرة يساوي قياس الزاوية المركزية التي تقابله. الزاوية المركزية المعطاة تساوي ٣٦°. لذلك يكون قياس القوس الصغير ب ج مساويًا ٣٦°.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كان س وص عددين صحيحين موجبين، وكان ص = ٢س، فقارن بين القيمة الأولى (س − ١) ÷ ص، والقيمة الثانية (س − ١) ÷ س.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 3, 'نعوض عن ص بالقيمة ٢س، فتصبح القيمة الأولى (س − ١) ÷ ٢س، بينما الثانية (س − ١) ÷ س. إذا كان س = ١، فإن القيمتين تساويان صفرًا. أما إذا كان س = ٢، فإن القيمة الأولى ١/٤ والثانية ١/٢، فتكون الثانية أكبر. إذن تختلف العلاقة باختلاف قيمة س.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'ما قيمة المجموع ١ + ٢ + ٣ + ٤ + ٥ + ٦ + ٦ + ٥ + ٤ + ٣ + ٢ + ١؟', '["٨ × ٧", "٧ × ٧", "٦ × ٧", "٧ × ٢"]'::jsonb, 2, 'نلاحظ أن الأعداد من ١ إلى ٦ وردت مرتين. مجموعها في المرة الواحدة = (٦ × ٧) ÷ ٢ = ٢١. نضرب في ٢ لأن المجموعة تكررت مرتين، فنحصل على ٢١ × ٢ = ٤٢، وهو يساوي ٦ × ٧.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في الشكل مستقيمان متوازيان، والضلعان المرسومان بينهما متعامدان. قارن بين القيمة الأولى، وهي قياس الزاوية س، والقيمة الثانية ١٢٠°.', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 2, 'الضلعان متعامدان، فالزاوية بينهما ٩٠°. الضلع الأيمن يصنع ٣٠° مع المستقيم العلوي، فيصنع الضلع الأيسر معه ١٨٠° − ٩٠° − ٣٠° = ٦٠°، وهي تساوي الزاوية الداخلية عند المستقيم السفلي بالتبادل. الزاوية س تكملها إلى زاوية مستقيمة: س = ١٨٠° − ٦٠° = ١٢٠°، فالقيمتان متساويتان.', 'https://czzcmbxejxbotjemyuqf.supabase.co/storage/v1/object/public/question-figures/qudurat_nov11_q027_perp.png', 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'مضلع خماسي، أربع من زواياه الداخلية قياساتها ١٣٠° و٦٠° و٩٠° و١٦٠°. ما قياس زاويته الداخلية الخامسة؟', '["٨٠°", "٩٠°", "١٠٠°", "١١٠°"]'::jsonb, 2, 'مجموع الزوايا الداخلية للخماسي = (٥ − ٢) × ١٨٠° = ٥٤٠°. نجمع الزوايا الأربع المعروفة: ١٣٠ + ٦٠ + ٩٠ + ١٦٠ = ٤٤٠°. إذن الزاوية الخامسة = ٥٤٠ − ٤٤٠ = ١٠٠°.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في الشكل مستطيل مقسَّم إلى ٦ مربعات، مساحة أحدها ٣٦ سم² ومساحة آخر ٢٥ سم² كما هو موضَّح. ما محيط المستطيل؟', '["٢٤ سم", "٣٦ سم", "٤٨ سم", "٦٠ سم"]'::jsonb, 2, 'ضلع المربع الأول = √٣٦ = ٦ سم، وضلع الثاني = √٢٥ = ٥ سم، فارتفاع المستطيل = ٦ + ٥ = ١١ سم. المربع الصغير بينهما ضلعه ٦ − ٥ = ١ سم، فضلع كل من المربعين السفليين = ٥ − ١ = ٤ سم، وضلع المربع العلوي الأكبر = ١١ − ٤ = ٧ سم. عرض المستطيل = ٦ + ٧ = ١٣ سم، والمحيط = ٢ × (١١ + ١٣) = ٤٨ سم.', 'https://czzcmbxejxbotjemyuqf.supabase.co/storage/v1/object/public/question-figures/qudurat_nov11_q030_squares.png', 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'اختر الزوج الذي يماثل العلاقة بين الكلمتين: شهد : عسل.', '["دبس : تمر", "إياب : عودة", "دفتر : قلم", "بدر : هلال"]'::jsonb, 1, 'الشهد اسم للعسل، وخاصة العسل الموجود في شمعه، ولذلك توجد علاقة تقارب شديد في المعنى بين الكلمتين. الإياب والعودة كذلك كلمتان مترادفتان تدلان على الرجوع. أما الدبس والتمر فعلاقتهما منتج ومصدره، والبدر والهلال مرحلتان مختلفتان من مراحل القمر.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'إكمال الجملة', 'اختيار من متعدد', 'احذر ........ إذا مازحته، واحذر ........ إذا عاشرته.', '["الكريم – اللئيم", "الأرعن – السافل", "الصادق – الأمين", "الحكيم – العاقل"]'::jsonb, 1, 'نختار الكلمتين وفق المعنى المقصود من التحذير. الأرعن شخص متهور قد يتصرف دون تفكير، ولذلك قد يسيء حتى أثناء المزاح. والسافل سيئ الخلق، فتكون معاشرته سببًا للأذى. أما الصفات الإيجابية في البدائل الأخرى فلا تنسجم مع معنى التحذير.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'إكمال الجملة', 'اختيار من متعدد', 'لا يمنعنَّ رجلًا ........ الناس أن يقول بالحق إذا ........ .', '["محبة – سمعه", "هيبة – علمه", "كثرة – فهمه", "قلة – بلغه"]'::jsonb, 1, 'المقصود أن الإنسان ينبغي ألا يخاف من مكانة الآخرين أو سلطتهم عندما يعرف الحق. كلمة «هيبة» تدل على الخوف المصحوب بالتعظيم، فتناسب المعنى الأول. وكلمة «علمه» تعني عرف الحق وتيقنه، فتكتمل الجملة بمعنى أن هيبة الناس لا ينبغي أن تمنعه من قوله.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'إكمال الجملة', 'اختيار من متعدد', 'عندما تبدأ في فهم ........، سترى كيف تصنع ........ الخاص.', '["أفكارك – واقعك", "مشاعرك – ماضيك", "أقوالك – خيالك", "أصدقاءك – مستقبلك"]'::jsonb, 0, 'الأفكار تؤثر في قرارات الإنسان وتصرفاته، ولذلك فإن فهمها يساعده على توجيه حياته. وكلمة «واقعك» تناسب فعل «تصنع» لأنها تشير إلى النتائج التي يسهم الإنسان في تحقيقها. أما الماضي فقد حدث بالفعل ولا يمكن صنعه من جديد، وبقية الخيارات أقل انسجامًا مع المعنى.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'لا شيء يبدد عزيمتك بسرعة مثل صحبة شخص مقاوم لملذاته. حدد الكلمة غير المناسبة للسياق.', '["عزيمتك", "بسرعة", "صحبة", "مقاوم"]'::jsonb, 3, 'تتحدث العبارة عن شخص تؤدي صحبته إلى إضعاف العزيمة. مقاومة الملذات تدل عادة على قوة الإرادة وضبط النفس، فلا تناسب هذا المعنى السلبي. الأنسب وصف الشخص بأنه مستسلم لملذاته بدلًا من مقاوم لها.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'رُبَّ مُبلَّغٍ حاضرٍ خيرٌ من سامعٍ شاهدٍ. حدد الكلمة غير المناسبة للسياق.', '["مُبلَّغ", "حاضر", "سامع", "شاهد"]'::jsonb, 1, 'المُبلَّغ هو الشخص الذي يصل إليه الخبر عن طريق غيره، بينما السامع قد يسمع الكلام مباشرة. تقارن العبارة بين من يتلقى الخبر بعد نقله ومن يحضر سماعه. لذلك لا تناسب كلمة «حاضر» وصف المُبلَّغ في هذه المقابلة، والأقرب إلى المعنى كلمة «غائب».', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'حسن الظن من الآداب الحميدة التي بها تكون الألفة والمحبة بين الناس، فمن حسن ظنه بالناس كان في نصب وهم لا ينقضي. حدد الكلمة غير المناسبة للسياق في العبارة الثانية.', '["الآداب", "حسن", "هم", "الألفة"]'::jsonb, 1, 'توضح بداية العبارة أن حسن الظن يؤدي إلى الألفة والمحبة. أما التعب والهم المستمران فيتناسبان مع سوء الظن بالآخرين، لا مع حسن الظن. لذلك يجب تغيير كلمة «حسن» في الجزء الأخير إلى «ساء»، لتصبح العبارة «فمن ساء ظنه بالناس».', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة من بين الكلمات الآتية.', '["تقاتل", "تشاجر", "تنازع", "تنازل"]'::jsonb, 3, 'تقاتل وتشاجر وتنازع كلها أفعال تدل على وجود خلاف أو صراع بين طرفين. أما تنازل فيعني التخلي عن حق أو مطلب، وقد يكون وسيلة لإنهاء الخلاف. لذلك تختلف هذه الكلمة عن بقية الكلمات في المعنى.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة من بين الكلمات الآتية.', '["بومة", "عقاب", "نعامة", "نسر"]'::jsonb, 2, 'البومة والعقاب والنسر من الطيور التي تستطيع الطيران. أما النعامة فهي طائر كبير لا يستطيع الطيران، رغم امتلاكه جناحين. لذلك تتميز النعامة عن بقية الطيور بهذه الصفة.', NULL, 'ad111126-2026-4c00-9d00-111120260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما علاقة عبارة «فإن نهر الطفل وزجره» بما قبلها في القطعة؟', '["تعقيب", "نتيجة", "تعليل", "تعارض"]'::jsonb, 2, 'تبدأ القطعة بتوجيه القارئ إلى ضرورة الاستماع للطفل عندما يتحدث. ثم توضح أن نهره وزجره يؤديان إلى ضعف ثقته بنفسه. هذه العبارة تذكر السبب الذي يجعل الاستماع إليه مهمًا، ولذلك فهي تعليل لما سبقها.', NULL, 'ad111126-2026-4c00-9d00-111120260001', 'e1b11001-2026-4c00-9d00-000000000001', 'زجر الطفل
يجب الاستماع لحديث الطفل عندما يتحدث؛ فإن نهر الطفل وزجره يولد فيه الشعور بعدم الثقة بالنفس.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما علاقة عبارة «يولد فيه الشعور بعدم الثقة بالنفس» بما قبلها؟', '["تعقيب", "نتيجة", "تعليل", "تعارض"]'::jsonb, 1, 'توضح العبارة أثر نهر الطفل وزجره. فالتعامل القاسي يحدث أولًا، ثم ينتج عنه الشعور بعدم الثقة بالنفس. عندما يذكر النص أثرًا مترتبًا على فعل سابق، تكون العلاقة نتيجة.', NULL, 'ad111126-2026-4c00-9d00-111120260001', 'e1b11001-2026-4c00-9d00-000000000001', 'زجر الطفل
يجب الاستماع لحديث الطفل عندما يتحدث؛ فإن نهر الطفل وزجره يولد فيه الشعور بعدم الثقة بالنفس.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما الاستنتاج الذي تدعمه القطعة بشأن إهمال الأطفال لوجبة الإفطار؟', '["إهمال وجبة الإفطار يقلل الوزن", "إهمال وجبة الإفطار يزيد احتمال زيادة الوزن إلى الضعف", "تناول وجبة الإفطار يقلل الوزن بالضرورة", "إهمال وجبة الإفطار يمنع زيادة الوزن"]'::jsonb, 1, 'تربط القطعة بين إهمال وجبة الإفطار وزيادة التعرض لارتفاع الوزن مقارنة بالأقران. عبارة «بمقدار الضعف» تشير إلى زيادة الخطر أو احتمالية التعرض، لا إلى أن وزن الطفل نفسه يتضاعف حتمًا. لذلك فالاستنتاج المدعوم هو ارتفاع احتمال زيادة الوزن عند إهمال الإفطار.', NULL, 'ad111126-2026-4c00-9d00-111120260001', 'e1b11002-2026-4c00-9d00-000000000002', 'وجبة الإفطار
إهمال الأطفال لوجبة الإفطار يجعلهم عرضة لزيادة الوزن بمقدار الضعف مقارنة بأقرانهم.', 1, 'active', false);
END IF;
END
$mig$;

UPDATE leak_groups SET question_count = (SELECT COUNT(*) FROM questions WHERE leak_group_id = 'ad111126-2026-4c00-9d00-111120260001') WHERE id = 'ad111126-2026-4c00-9d00-111120260001';

DO $chk$
DECLARE n INT; nq INT; nv INT;
BEGIN
  SELECT COUNT(*) INTO n FROM questions WHERE leak_group_id = 'ad111126-2026-4c00-9d00-111120260001';
  SELECT COUNT(*) INTO nq FROM questions WHERE leak_group_id = 'ad111126-2026-4c00-9d00-111120260001' AND section = 'quant';
  SELECT COUNT(*) INTO nv FROM questions WHERE leak_group_id = 'ad111126-2026-4c00-9d00-111120260001' AND section = 'verbal';
  RAISE NOTICE 'إجمالي: % — كمي: % — لفظي: %', n, nq, nv;
  IF n <> 24 THEN RAISE EXCEPTION 'عدد الأسئلة % لا يطابق المتوقع 24', n; END IF;
  IF nq <> 12 OR nv <> 12 THEN RAISE EXCEPTION 'توزيع كمي/لفظي غير مطابق'; END IF;
END
$chk$;

COMMIT;
